import 'package:flutter/material.dart'; import '../../repositories/course_repository.dart'; import '../../widgets/course_card.dart'; import 'course_details_page.dart'; class CoursesPage extends StatelessWidget { const CoursesPage({super.key}); @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('دوراتي')),body:StreamBuilder(stream:CourseRepository().watch(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final data=s.data!;if(data.isEmpty)return const Center(child:Text('لا توجد دورات متاحة حاليًا'));return ListView(padding:const EdgeInsets.all(12),children:data.map((x)=>CourseCard(course:x,onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>CourseDetailsPage(course:x))))).toList());})); }